package cn.zhuatech.customerservice.deep;import cn.zhuatech.customerservice.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.time.*;@RestController @RequestMapping("/api/service") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/customers")ApiResponse<?> customer(@Valid @RequestBody DeepDomainService.CustomerRequest r){return ApiResponse.ok(s.createCustomer(r));}@PostMapping("/tickets")ApiResponse<?> ticket(@Valid @RequestBody DeepDomainService.TicketRequest r){return ApiResponse.ok(s.createTicket(r));}@PostMapping("/tickets/{id}/assign")ApiResponse<?> assign(@PathVariable Long id,@Valid @RequestBody DeepDomainService.AssignRequest r){return ApiResponse.ok(s.assign(id,r));}@PostMapping("/tickets/{id}/messages")ApiResponse<?> message(@PathVariable Long id,@Valid @RequestBody DeepDomainService.MessageRequest r){return ApiResponse.ok(s.message(id,r));}@PostMapping("/tickets/{id}/resolve")ApiResponse<?> resolve(@PathVariable Long id,@Valid @RequestBody DeepDomainService.ResolveRequest r){return ApiResponse.ok(s.resolve(id,r));}@PostMapping("/tickets/{id}/close")ApiResponse<?> close(@PathVariable Long id){return ApiResponse.ok(s.close(id));}@PostMapping("/tickets/{id}/reopen")ApiResponse<?> reopen(@PathVariable Long id,@Valid @RequestBody DeepDomainService.ReopenRequest r){return ApiResponse.ok(s.reopen(id,r));}@PostMapping("/sla/escalate")ApiResponse<?> escalate(@RequestParam String organizationCode,@RequestParam LocalDateTime asOf){return ApiResponse.ok(s.escalate(organizationCode,asOf));}@PostMapping("/knowledge")ApiResponse<?> article(@Valid @RequestBody DeepDomainService.ArticleRequest r){return ApiResponse.ok(s.createArticle(r));}@PostMapping("/knowledge/{id}/submit")ApiResponse<?> submit(@PathVariable Long id){return ApiResponse.ok(s.submitArticle(id));}@GetMapping("/knowledge/search")ApiResponse<?> search(@RequestParam String organizationCode,@RequestParam String keyword){return ApiResponse.ok(s.searchKnowledge(organizationCode,keyword));}}
